<?php
require_once __DIR__ . '/includes/functions.php'; require_login(); require_once __DIR__ . '/config/database.php';
$pageTitle = 'Products';
$edit = null;
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
 verify_csrf(); $action = $_POST['action'] ?? '';
 if ($action === 'save') {
  $id = (int)($_POST['id'] ?? 0); $sku = trim($_POST['sku'] ?? ''); $name = trim($_POST['name'] ?? ''); $category = ($_POST['category_id'] ?? '') !== '' ? (int)$_POST['category_id'] : null;
  $cost = (float)($_POST['cost_price'] ?? 0); $price = (float)($_POST['selling_price'] ?? 0); $qty = (int)($_POST['quantity'] ?? 0); $reorder = (int)($_POST['reorder_level'] ?? 5); $desc = trim($_POST['description'] ?? '');
  if ($sku === '' || $name === '' || $cost < 0 || $price < 0 || $qty < 0 || $reorder < 0) { flash('danger','Enter a product name, SKU, and valid non-negative prices/stock values.'); redirect('products.php' . ($id ? '?edit='.$id : '')); }
  try {
   if ($id) { $q=$pdo->prepare('UPDATE products SET category_id=?,sku=?,name=?,description=?,cost_price=?,selling_price=?,quantity=?,reorder_level=? WHERE id=?'); $q->execute([$category,$sku,$name,$desc,$cost,$price,$qty,$reorder,$id]); flash('success','Product updated successfully.'); }
   else { $q=$pdo->prepare('INSERT INTO products(category_id,sku,name,description,cost_price,selling_price,quantity,reorder_level) VALUES(?,?,?,?,?,?,?,?)'); $q->execute([$category,$sku,$name,$desc,$cost,$price,$qty,$reorder]); flash('success','Product saved to MySQL successfully.'); }
  } catch (PDOException $ex) { flash('danger', $ex->getCode()==='23000' ? 'SKU already exists. Use a unique SKU.' : 'Could not save product. Check the values and database.'); }
  redirect('products.php');
 }
 if ($action === 'delete') { $id=(int)($_POST['id']??0); try {$q=$pdo->prepare('DELETE FROM products WHERE id=?');$q->execute([$id]);flash('success','Product deleted.');}catch(PDOException $ex){flash('danger','This product is already used in a sale and cannot be deleted.');} redirect('products.php'); }
}
if (isset($_GET['edit'])) { $q=$pdo->prepare('SELECT * FROM products WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch(); }
$categories=$pdo->query('SELECT id,name FROM categories ORDER BY name')->fetchAll();
$search=trim($_GET['q']??''); $lowOnly=($_GET['stock']??'')==='low';
$sql='SELECT p.*,c.name AS category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id'; $where=[];$params=[];
if($search!==''){$where[]='(p.name LIKE ? OR p.sku LIKE ?)';$params[]='%'.$search.'%';$params[]='%'.$search.'%';} if($lowOnly)$where[]='p.quantity <= p.reorder_level'; if($where)$sql.=' WHERE '.implode(' AND ',$where);$sql.=' ORDER BY p.name';$stmt=$pdo->prepare($sql);$stmt->execute($params);$products=$stmt->fetchAll();
require __DIR__ . '/includes/header.php';
?>
<div class="row"><div class="col-lg-4"><div class="card card-primary card-outline form-card"><div class="card-header"><h3 class="card-title"><?= $edit?'Edit Product':'Add Product' ?></h3></div><form method="post"><div class="card-body"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>">
<div class="form-group"><label class="required">SKU / Product Code</label><input class="form-control" name="sku" required maxlength="60" value="<?= e($edit['sku']??'') ?>" placeholder="e.g. MOU-001"></div><div class="form-group"><label class="required">Product Name</label><input class="form-control" name="name" required maxlength="150" value="<?= e($edit['name']??'') ?>" placeholder="Product name"></div>
<div class="form-group"><label>Category</label><select name="category_id" class="form-control"><option value="">-- No category --</option><?php foreach($categories as $c): ?><option value="<?= (int)$c['id'] ?>" <?= (string)($edit['category_id']??'')===(string)$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></div>
<div class="row"><div class="col-6"><div class="form-group"><label>Cost price (TZS)</label><input type="number" min="0" step="0.01" class="form-control" name="cost_price" value="<?= e($edit['cost_price']??'0') ?>" required></div></div><div class="col-6"><div class="form-group"><label>Selling price (TZS)</label><input type="number" min="0" step="0.01" class="form-control" name="selling_price" value="<?= e($edit['selling_price']??'0') ?>" required></div></div></div>
<div class="row"><div class="col-6"><div class="form-group"><label>Quantity in stock</label><input type="number" min="0" step="1" class="form-control" name="quantity" value="<?= e($edit['quantity']??'0') ?>" required></div></div><div class="col-6"><div class="form-group"><label>Reorder level</label><input type="number" min="0" step="1" class="form-control" name="reorder_level" value="<?= e($edit['reorder_level']??'5') ?>" required></div></div></div><div class="form-group"><label>Description</label><textarea name="description" class="form-control" rows="2"><?= e($edit['description']??'') ?></textarea></div></div><div class="card-footer"><button class="btn btn-primary"><i class="fas fa-save mr-1"></i><?= $edit?'Update Product':'Save Product' ?></button><?php if($edit): ?> <a href="products.php" class="btn btn-default">Cancel</a><?php endif; ?></div></form></div></div>
<div class="col-lg-8"><div class="card"><div class="card-header"><h3 class="card-title">Product List (<?= count($products) ?>)</h3><div class="card-tools"><form class="input-group input-group-sm" method="get" style="width:230px"><input type="text" name="q" value="<?= e($search) ?>" class="form-control float-right" placeholder="Search name or SKU"><div class="input-group-append"><button class="btn btn-default"><i class="fas fa-search"></i></button></div></form></div></div><div class="card-body table-responsive p-0"><table class="table table-hover table-striped"><thead><tr><th>SKU</th><th>Product</th><th>Category</th><th>Price (TZS)</th><th>Qty</th><th>Actions</th></tr></thead><tbody><?php if(!$products): ?><tr><td colspan="6" class="empty-state"><i class="fas fa-box-open d-block"></i>No products found. Add one using the form.</td></tr><?php else: foreach($products as $p): ?><tr><td><?= e($p['sku']) ?></td><td><strong><?= e($p['name']) ?></strong><br><small class="text-muted"><?= e($p['description']) ?></small></td><td><?= e($p['category_name']??'—') ?></td><td><?= money($p['selling_price']) ?></td><td><span class="badge badge-<?= $p['quantity'] <= $p['reorder_level']?'danger':'success' ?>"><?= (int)$p['quantity'] ?></span></td><td class="text-nowrap"><a href="products.php?edit=<?= (int)$p['id'] ?>" class="btn btn-xs btn-info" title="Edit"><i class="fas fa-edit"></i></a> <form method="post" class="d-inline"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><button class="btn btn-xs btn-danger" data-confirm="Delete this product?" title="Delete"><i class="fas fa-trash"></i></button></form></td></tr><?php endforeach; endif; ?></tbody></table></div></div></div></div>
